{
  "API_calls": [],
  "collected_information": {
    "README.md": {
      "install": "python -m pip install aider-install",
      "usage": "aider-install",
      "notes": "Usage requires LLM API keys (DeepSeek, Claude 3.7 Sonnet, o3-mini)",
      "documentation_url": "https://aider.chat/docs/"
    },
    "requirements_and_pyproject": {
      "python_version": ">=3.10,<3.13",
      "main_dependencies": [
        "aiohttp==3.12.9",
        "pydantic==2.11.5",
        "openai==1.84.0",
        "google-api-python-client==2.171.0",
        "numpy==1.26.4",
        "protobuf==5.29.5"
      ],
      "dev_dependencies": [
        "pytest",
        "flake8"
      ],
      "optional_dependencies": [
        "browser",
        "help",
        "playwright"
      ],
      "build_system": {
        "setuptools": ">=68",
        "setuptools_scm[toml]": ">=8"
      },
      "dev_dependencies_file": "requirements/requirements-dev.txt"
    },
    "Dockerfile": {
      "base_image": "python:3.10-slim",
      "system_packages": [
        "build-essential",
        "git",
        "libportaudio2",
        "pandoc"
      ],
      "pip_upgrade_command": "/venv/bin/python -m pip install --upgrade --no-cache-dir pip",
      "package_installation": {
        "local_package_extras": [
          "help",
          "browser",
          "playwright"
        ],
        "additional_packages": [
          "boto3"
        ],
        "pytorch_cpu_wheel_url": true,
        "google_cloud_aiplatform": true
      }
    },
    "Testing_and_Contributing": {
      "python_version_recommendation": "3.9+",
      "environment_setup": [
        "Clone repo",
        "Create and activate Python virtual environment",
        "Install project in editable mode: pip install -e .",
        "Install main dependencies: pip install -r requirements.txt",
        "Install dev dependencies: pip install -r requirements/requirements-dev.txt"
      ],
      "test_commands": [
        "pytest",
        "pytest tests/basic/test_coder.py",
        "pytest tests/basic/test_coder.py::TestCoder::test_specific_case"
      ],
      "pre_commit_hooks": "Available for linting and formatting (optional)",
      "test_locations": "tests/ directory, e.g., tests/basic/test_models.py"
    }
  },
  "terminate": true
}
